import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

private fun funSolve(x: Int, a: Int, b: Int, initialC: Int, count: IntArray) {
    var c = initialC
    if (a != x || b != x || c != x) {
        if (c != x) {
            c = if (a + b > x) x else b + a - 1
            count[0]++
        }
        funSolve(x, c, a, b, count)
    }
}

fun main() {
    val scanner = FastScanner()
    val x = scanner.nextInt()
    val y = scanner.nextInt()
    val count = intArrayOf(0)
    funSolve(x, y, y, y, count)
    print(count[0])
    print('\n')
}

